const issueGuides = [{"name": "Mould or musty smells", "intro": "Mould may look like dark patches or have a musty smell. It can return when moisture problems continue.", "law": "Mould is not a separate Healthy Homes Standard. Ventilation, moisture ingress and drainage requirements may apply. Landlords also have duties to maintain the property in a reasonable state of repair.", "action": "Notice where mould appears, whether it returns, and any leaks or broken fans. A photo alone cannot prove a breach."}, {"name": "Dampness or condensation", "intro": "Water droplets on windows, wet walls or a damp smell may indicate excess moisture.", "law": "Ventilation and moisture ingress and drainage standards may be relevant. Condensation alone does not prove a breach.", "action": "Record where and when water appears. Check whether windows open and fans work."}, {"name": "Inadequate or faulty heating", "intro": "A living room may stay cold because a heater is broken, unsuitable or insufficient.", "law": "The heating standard generally requires qualifying fixed heating in the main living room, with capacity calculated for that room. Specific rules and exemptions apply.", "action": "Record what heater is installed and what happens when you use it. Ask for the heating compliance information."}, {"name": "Poor ventilation or extractor fans", "intro": "A room may feel stuffy, windows may not open, or an extractor fan may not work.", "law": "The ventilation standard covers openable windows in habitable rooms and qualifying extractor fans in kitchens and bathrooms, subject to applicable rules and exemptions.", "action": "Check whether windows can open and whether fans operate and vent outdoors, without dismantling equipment."}, {"name": "Insulation concerns", "intro": "You may be unsure whether the ceiling or underfloor insulation is present or adequate.", "law": "The insulation standard generally covers ceiling and underfloor insulation where applicable, with technical requirements and exceptions.", "action": "Ask for the insulation statement or compliance information. Do not enter ceiling or subfloor spaces."}, {"name": "Draughts or gaps", "intro": "Unwanted air may enter through gaps around doors, windows or other openings.", "law": "The draught-stopping standard requires landlords to block unreasonable gaps and holes that cause noticeable draughts. Some openings and exceptions are treated differently.", "action": "Note the exact gap and when the draught occurs. Do not block necessary ventilation."}, {"name": "Leaks, guttering or drainage problems", "intro": "Water may leak indoors or collect around the property after rain.", "law": "The moisture ingress and drainage standard covers effective drainage, including gutters, downpipes and drains, and ground moisture barriers where required. Repair duties may also apply.", "action": "Record the location and timing of leaks. Avoid unsafe electrical or structural areas."}, {"name": "Both heating and dampness", "intro": "Cold rooms and damp surfaces may have several related causes.", "law": "Heating, ventilation and moisture ingress standards may all need consideration. Each requirement has its own tests and exceptions.", "action": "Record heating and dampness separately, including the affected rooms."}, {"name": "I’m not sure", "intro": "You do not need to identify the cause before seeking information.", "law": "The five Healthy Homes Standards cover heating, insulation, ventilation, moisture ingress and drainage, and draught stopping. Other tenancy maintenance duties may apply.", "action": "Start with what you can see, smell or experience. You can ask for independent advice."}, {"name": "Another housing concern", "intro": "Other issues may include repairs, safety or maintenance.", "law": "Not every housing problem is a Healthy Homes Standards issue. Other obligations under tenancy law may be relevant.", "action": "Describe the problem and seek advice about the appropriate pathway."}];

function issueDetailPage(){
 const i=Math.max(0,concerns.findIndex(x=>x[0]===state.concern));
 const g=issueGuides[i];
 return `<main id="main" class="wrap issue-detail">
 <button class="back" data-back>← Back to all pictures</button>
 <div class="eyebrow">EXPLORE YOUR HOUSING CONCERN</div>
 <h1>${esc(g.name)}</h1>
 <p class="intro">Understand the signs, relevant New Zealand rules, and choices available to you.</p>
 <div class="issue-detail-grid"><div>${i<8?sampleTile(i,'issue-hero-photo'):`<div class="text-picture">${esc(concerns[i][2])}</div>`}<p class="fine">Illustrative example only. A picture cannot establish compliance.</p></div>
 <div class="issue-detail-content">
 <section class="issue-section"><h2>What am I looking at?</h2><p>${esc(g.intro)}</p></section>
 <section class="issue-section"><h2>⚖ Legal requirements, in simple language</h2><p>${esc(g.law)}</p><p class="fine">These are simplified explanations, not a legal determination. The full regulations, dates, exemptions and property circumstances matter.</p>
 <a href="https://www.tenancy.govt.nz/healthy-homes/healthy-homes-standards-what-a-tenant-needs-to-know/" target="_blank" rel="noopener">Read official Tenancy Services guidance ↗</a></section>
 <section class="issue-section"><h2>✓ What can I check?</h2><p>${esc(g.action)}</p><button class="btn secondary small" data-go="13">Open my home checklist →</button></section>
 <section class="issue-section"><h2>♧ Choose a safe next step</h2><p>You can keep a private record, explore your concerns, or speak to an independent support service before contacting your landlord. The app will not report anything automatically.</p>
 <div class="toolbar"><button class="btn" data-go="2">Describe my concern →</button><button class="btn secondary" data-go="3">Explore my worries →</button><button class="btn secondary" data-go="12">Find independent support ↗</button></div></section>
 <section class="issue-section"><h2>What about a 14-day notice?</h2><p>A tenant may be able to use a formal notice to remedy a breach. It is not the only first step, and a maintenance request is different from a formal notice. Get advice on the appropriate process and wording before taking action if you are concerned about retaliation or your housing security.</p><a href="https://www.tenancy.govt.nz/" target="_blank" rel="noopener">Check the current official process ↗</a></section>
 </div></div><div class="notice warm">Research prototype only. Use fictional information when testing. No photo-based diagnosis or automatic reporting.</div></main>`;
}
const $=s=>document.querySelector(s);
const titles=['Welcome','Your concern','What is happening','Your worries','Understand your options','Choose your next step','Organise evidence','Review your summary','Prepare a request','Your sharing choices','Your action plan','Track progress','Support & finish'];
const concerns=[['Mould or musty smells','Visible mould, recurring patches or unusual smells','◌'],['Dampness or condensation','Wet surfaces, moisture or condensation on windows','◊'],['Inadequate or faulty heating','A room that is difficult to keep warm','♨'],['Poor ventilation or extractor fans','Stuffy rooms or fans that do not seem to work','≋'],['Insulation concerns','Questions about ceiling or underfloor insulation','▱'],['Draughts or gaps','Cold air coming through gaps or openings','≈'],['Leaks, guttering or drainage problems','Water entering the home or not draining away','⌁'],['Both heating and dampness','More than one concern in your home','⌂'],["I’m not sure",'Explore what you have noticed','?'],['Another housing concern','Describe a concern that is not listed here','＋']];
const pictureLabels=['AI-generated example: mould-like patches on a wall','AI-generated example: condensation on a window','AI-generated example: a living-room heater','AI-generated example: an extractor fan','AI-generated example: underfloor insulation','AI-generated example: a gap beside a window','AI-generated example: a water stain below a window','AI-generated example: a living room','AI-generated example: a notebook beside a window'];
const checklistSource='https://www.tenancy.govt.nz/assets/Uploads/the-healthy-homes-standards-checklist.pdf';
const homeChecks=[
{title:'Heating',icon:'♨',items:['Does the main living space have a heater?','Is the heater permanently installed?','Do records confirm suitable heating output and type?']},
{title:'Insulation',icon:'▱',items:['Do records identify ceiling insulation?','Do records identify underfloor insulation where applicable?','Is insulation condition and performance documented?']},
{title:'Ventilation',icon:'≋',items:['Can living spaces open to outdoor air?','Is kitchen extraction provided?','Is bathroom extraction provided?','Is extraction working and vented outdoors?']},
{title:'Moisture ingress & drainage',icon:'◊',items:['Do roof gutters and downpipes drain effectively?','Does surface water drain away?','Is a ground moisture barrier documented where needed?']},
{title:'Draught stopping',icon:'≈',items:['Are windows and doors closing without noticeable draughts?','Are unwanted gaps or holes sealed?','Is an unused fireplace blocked or its exception documented?']}
];
function allCheckItems(){return homeChecks.flatMap((g,gi)=>g.items.map((text,i)=>({id:`${gi}-${i}`,text,group:g.title}))).concat(state.checklist.custom.map(x=>({...x,group:'My own observations'})))}
function checkStats(){const a=state.checklist.answers,items=allCheckItems();return {total:items.length,answered:items.filter(x=>a[x.id]).length,review:items.filter(x=>a[x.id]==='No'||a[x.id]==='Not sure').length}}
function checkItem(x){const c=state.checklist;return `<div class="checklist-item"><div class="checklist-question"><label for="check-${x.id}">${esc(x.text)}</label>${x.group==='My own observations'?`<button class="remove" data-delete-check="${x.id}">Remove</button>`:''}<select id="check-${x.id}" data-check-answer="${x.id}" aria-label="${esc(x.text)}"><option value="">Choose</option>${['Yes','No','Not sure','Not applicable'].map(v=>`<option ${c.answers[x.id]===v?'selected':''}>${v}</option>`).join('')}</select></div><label class="checklist-note-label">My notes<input data-check-note="${x.id}" value="${esc(c.notes[x.id]||'')}" placeholder="Optional: location, date or a question to ask"></label></div>`}
function checklistText(){return 'MY HEALTHY HOMES OBSERVATION CHECKLIST\nSimplified tenant worksheet — not the official form or a compliance result.\nOfficial checklist: '+checklistSource+'\n\n'+allCheckItems().map(x=>`${x.group} | ${x.text}\nAnswer: ${state.checklist.answers[x.id]||'Not answered'}\nNotes: ${state.checklist.notes[x.id]||'None'}\n`).join('\n')+'\nNo / Not sure answers are discussion prompts, not findings of a breach. Requirements and exemptions need checking.'}
function checklistPage(){const stats=checkStats();return `<main id="main" class="wrap checklist-page"><button class="back" data-back>← Back to previous page</button><div class="checklist-top"><div><div class="eyebrow">MY HOME · MY OBSERVATIONS</div><h1>A clearer picture of your home.</h1><p class="intro">Work through a simplified tenant worksheet inspired by the five areas in the Tenancy Services checklist. Record what you know and what you want to ask.</p></div><div class="checklist-source"><span class="pill">OFFICIAL RESOURCE</span><h3>Tenancy Services checklist</h3><p>Open the original PDF for full questions and guidance.</p><a class="btn secondary small" href="${checklistSource}" target="_blank" rel="noopener">Open official checklist ↗</a><p class="fine" style="margin-top:12px">Source reviewed 28 October 2026</p></div></div><div class="notice">This is your own observation record, not the official checklist or a pass/fail assessment. Use records and safely visible information; do not enter roof or subfloor spaces. “Not sure” is a useful answer. Full requirements, alternatives and exemptions still need checking.</div><div class="checklist-progress"><span id="check-progress">${stats.answered} of ${stats.total} answered · ${stats.review} to discuss or clarify</span><span>Session only · not shared</span></div><div class="checklist-columns">${homeChecks.map((g,gi)=>`<section class="checklist-group"><div class="checklist-group-title"><span>${g.icon}</span><h2>${g.title}</h2></div>${g.items.map((text,i)=>checkItem({id:`${gi}-${i}`,text,group:g.title})).join('')}</section>`).join('')}<section class="checklist-group"><div class="checklist-group-title"><span>＋</span><h2>My own observations</h2></div><p class="fine">Add your own check, such as a recurring mould patch or a repair question. Keep examples fictional during testing.</p>${state.checklist.custom.map(x=>checkItem({...x,group:'My own observations'})).join('')}<button class="btn secondary small" data-add-check>＋ Add my own checklist item</button></section></div><div class="notice warm"><strong>What do my answers mean?</strong> “No” and “Not sure” identify things to explore or clarify. They are not a compliance score. “Yes” answers do not confirm the home meets the standards.</div><div class="toolbar"><button class="btn" data-download-check>Download my checklist ↓</button><button class="btn secondary" data-check-to-plan>Add review task to my plan</button><button class="btn secondary" data-go="1">Explore a housing concern →</button><button class="btn secondary" data-go="12">Find support ↗</button><button class="back" data-go="0">Back to overview</button></div><p class="fine">Answers, notes and your own items save automatically for this browser tab’s session. Use Your privacy → Delete demo information to clear them.</p></main>`}
function updateCheckProgress(){const stats=checkStats(),p=$('#check-progress');if(p)p.textContent=`${stats.answered} of ${stats.total} answered · ${stats.review} to discuss or clarify`}
function downloadChecklist(){const u=URL.createObjectURL(new Blob([checklistText()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='My-Healthy-Homes-Checklist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Your checklist downloaded. Nothing submitted.')}
function sampleTile(i,cls=''){return `<span class="sample-picture ${cls}" style="--tile-x:${(i%3)*50}%;--tile-y:${Math.floor(i/3)*50}%" role="img" aria-label="${pictureLabels[i]}"><span class="sample-badge">AI-generated example</span></span>`}
function visualConcerns(){return `<div class="visual-choices">${concerns.map(([l,sub,icon],i)=>`<button class="visual-choice ${state.concern===l?'selected':''}" data-concern="${esc(l)}" aria-pressed="${state.concern===l}">${i<8?sampleTile(i):`<span class="text-picture">${icon}</span>`}<span class="visual-choice-body"><strong>${esc(l)}</strong><small>${esc(sub)}</small><span class="visual-choice-action">${state.concern===l?'✓ Selected':'Explore this concern →'}</span></span></button>`).join('')}</div>`}
let localPhoto=null,photoRead=0,photoObservation='',photoPattern='',photoResult=false;
function removeLocalPhoto(){photoRead++;if(localPhoto)URL.revokeObjectURL(localPhoto.url);localPhoto=null;photoResult=false}
function photoTool(){return `<section class="photo-tool" id="photo-check"><div class="photo-tool-heading"><div><div class="eyebrow">LOOK · DESCRIBE · EXPLORE</div><h2>A picture is a starting point.</h2><p>Preview a photo and tell us what you notice. We’ll suggest a pathway from your answers.</p></div><span class="photo-status">Guided check · no AI analysis</span></div><div class="photo-workspace"><div><label class="photo-drop" for="local-photo">${localPhoto?`<img src="${localPhoto.url}" alt="Your locally selected photo preview"><span class="upload-overlay">Choose a different photo</span>`:'<span class="upload-symbol">＋</span><strong>Choose a photo to preview</strong><span>JPG, PNG or WebP · up to 8 MB</span><small>Stays in this page. Not sent to a server.</small>'}</label><input class="file-input" id="local-photo" type="file" accept="image/jpeg,image/png,image/webp"><p class="fine photo-file-status" id="photo-file-status" role="status">${localPhoto?'Photo loaded locally. You can remove it at any time.':'Use a non-identifying sample photo for this research prototype.'}</p>${localPhoto?'<button class="back" data-remove-photo>Remove photo ×</button>':''}</div><div><label>What do you notice in the photo?<select id="photo-observation"><option value="">Choose an observation</option>${concerns.slice(0,8).map(([l])=>`<option value="${esc(l)}" ${photoObservation===l?'selected':''}>${esc(l)}</option>`).join('')}<option value="unclear" ${photoObservation==='unclear'?'selected':''}>No clear issue / I’m not sure</option></select></label><label style="margin-top:16px">Have you noticed this more than once?<select id="photo-pattern"><option value="">Choose what you know</option>${[['recurring','Yes, it keeps happening'],['once','I have noticed it once'],['unsure','I’m not sure']].map(([v,l])=>`<option value="${v}" ${photoPattern===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn" style="margin-top:20px" data-photo-check>Explore possible concern <span>→</span></button><p class="fine" style="margin-top:13px">This check uses your selections, not the image pixels. It cannot identify mould, measure heating or insulation, or confirm that a home passes or fails a standard.</p></div></div>${photoResult?photoResultMarkup():''}</section>`}
function photoResultMarkup(){let unclear=photoObservation==='unclear';return `<div class="photo-result" role="status"><span class="result-icon">${unclear?'?':'↗'}</span><div><div class="eyebrow">BASED ON YOUR ANSWERS · NOT IMAGE ANALYSIS</div><h3>${unclear?'More information is needed':'A possible housing concern to explore'}</h3><p>${unclear?'A photo without an obvious sign cannot rule out a housing issue. You can describe what you notice in daily use, review the examples or seek independent advice.':`You selected “${esc(photoObservation)}”. ${photoPattern==='recurring'?'Because you report that it keeps happening, recording dates and changes may help you describe the concern.':'Record what you noticed and when; further information may help explain it.'} The cause and whether any standard applies still need to be checked.`}</p><p class="fine">A photo cannot confirm compliance. Heating capacity, insulation specifications, ventilation, drainage and possible exemptions may require records, measurements or an appropriate assessment.</p><div class="toolbar">${unclear?'<button class="btn secondary small" data-go="2">Describe what I know →</button>':`<button class="btn small" data-use-photo-concern>Continue with this concern →</button>`}<button class="btn secondary small" data-go="12">Find independent support ↗</button></div></div></div>`}
const concernProfiles={
'Mould or musty smells':{question:'Where is the mould or smell, and what have you noticed?',example:'e.g. Mould patches near the bedroom window and a musty smell.',info:'Mould and musty smells can have different causes. Moisture ingress, drainage and ventilation may be relevant. A visible patch does not by itself establish a breach. Record where it appears and consider independent advice.',note:'Fictional example: mould patches and a musty smell near the bedroom window.',photo:'Fictional illustration: mould patches beside a window.',draft:'mould or a musty smell'},
'Dampness or condensation':{question:'Where do you notice moisture or condensation, and when does it appear?',example:'e.g. Water on the inside of the bedroom windows each morning.',info:'Dampness and condensation can have different causes. Ventilation, moisture ingress and drainage may be relevant. Document where and when you notice moisture; further advice or assessment may help identify the cause.',note:'Fictional example: moisture gathers on the bedroom window each morning.',photo:'Fictional illustration: condensation on a window.',draft:'dampness or condensation'},
'Inadequate or faulty heating':{question:'What happens when you try to heat the home?',example:'e.g. The heater switches off and the living room stays cold.',info:'Healthy Homes standards include heating requirements for rental homes. Record how the heater operates and which area stays cold. A cold room or faulty heater is worth investigating, but this prototype cannot confirm compliance.',note:'Fictional example: the living room heater switches off and the room stays cold.',photo:'Fictional illustration: a heater in the living room.',draft:'a heating problem'},
'Poor ventilation or extractor fans':{question:'Which windows or fans are affected, and what happens when you use them?',example:'e.g. The bathroom extractor fan does not turn on.',info:'Healthy Homes standards include ventilation requirements. Record the affected room and what you notice about windows or extractor fans. The applicable requirements and any exemptions need to be checked for the home.',note:'Fictional example: the bathroom extractor fan does not turn on.',photo:'Fictional illustration: a bathroom extractor fan.',draft:'a ventilation or extractor-fan problem'},
'Insulation concerns':{question:'What makes you concerned about the insulation?',example:'e.g. The insulation statement is unclear about the underfloor area.',info:'Healthy Homes standards include insulation requirements. The tenancy agreement’s insulation or Healthy Homes statement may help you understand what is recorded. You do not need to enter a roof space or go under the home to use this tool; seek advice or an appropriate assessment.',note:'Fictional example: the insulation statement is unclear about the underfloor area.',photo:'Fictional illustration: an insulation statement with a question marked.',draft:'an insulation concern'},
'Draughts or gaps':{question:'Where does cold air enter, and when do you notice it?',example:'e.g. A draught comes through a gap beneath the living room door.',info:'Healthy Homes standards include draught-stopping requirements. Record the location of gaps and when you notice incoming air. Not every opening is a compliance failure; the home may need further assessment.',note:'Fictional example: cold air enters through a gap beside the living room window.',photo:'Fictional illustration: a gap beside a window frame.',draft:'draughts or gaps'},
'Leaks, guttering or drainage problems':{question:'Where does water enter or collect, and does it happen during rain?',example:'e.g. Water drips near the window when it rains.',info:'Healthy Homes standards include moisture-ingress and drainage requirements. Leaks can also involve wider repair concerns. Record the location and timing of water entry or pooling and consider support about an appropriate next step.',note:'Fictional example: water drips beside the living room window during rain.',photo:'Fictional illustration: water marks beside a window.',draft:'a leak or drainage problem'},
'Both heating and dampness':{question:'What have you noticed about both the heating and moisture?',example:'e.g. The living room stays cold and the windows are wet each morning.',info:'Heating, ventilation, moisture ingress and drainage may all be relevant when a home feels cold and damp. Record each observation separately. This prototype cannot determine the cause or confirm compliance.',note:'Fictional example: the living room stays cold and the windows are wet each morning.',photo:'Fictional illustration: a window with condensation near a heater.',draft:'heating and dampness concerns'}
};
concernProfiles['Inadequate heating']=concernProfiles['Inadequate or faulty heating'];
concernProfiles['Dampness or mould']=concernProfiles['Mould or musty smells'];
function profile(){return concernProfiles[state.concern]||{question:'What have you noticed?',example:'Describe a fictional example of your concern.',info:'The standards cover heating, insulation, ventilation, moisture ingress and drainage, and draught stopping. Other housing concerns may involve wider maintenance or safety issues. Explore official guidance or independent support to understand which pathway may fit.',note:'Fictional example: a concern has been noticed and needs further advice.',photo:'Fictional illustration: a record of a housing concern.',draft:'a housing concern'}}
function isMoisture(){return /mould|dampness|condensation/i.test(state.concern)}

const worries=['My landlord may react badly','My rent may increase','I may lose my housing','I do not know my rights or options','I have language or communication difficulties','I am worried about conflict or safety','I am not ready to contact anyone yet','Something else'];
const options=['Organise sample evidence','Draft a maintenance request','Find independent help','Make a private action plan','I am not ready to contact my landlord'];
const blank=()=>({step:0,concern:'',area:'',since:'',observation:'',affected:'',returns:'',previous:'',otherWorry:'',worries:[],options:[],evidence:[],seeded:false,draft:'',summary:'',includeEvidence:true,removePersonal:false,followup:'',tasks:[],events:[],feedback:{},checklist:{answers:{},notes:{},custom:[]}});
let state;try{state=JSON.parse(sessionStorage.getItem('hhn-demo'))||blank()}catch{state=blank()}
state={...blank(),...state};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{sessionStorage.setItem('hhn-demo',JSON.stringify(state))}catch{} }
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
const pageHistory=[];
function go(n,fromBack=false){
 if(!fromBack && n!==state.step)pageHistory.push(state.step);
 state.step=n;save();render();scrollTo({top:0,behavior:'instant'});const h=$('main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}
function backPage(){
 const previous=pageHistory.pop();
 if(previous!==undefined && previous!==state.step){go(previous,true);return;}
 const current=state.step;
 go(current===14?1:current===13?0:Math.max(0,current-1),true);
}
function heading(k,title,description){return `<div class="eyebrow">${k}</div><h1>${title}</h1><p class="intro">${description}</p>`}
function field(label,key,type='text',placeholder=''){return `<label>${label}<input type="${type}" data-field="${key}" value="${esc(state[key])}" placeholder="${placeholder}"></label>`}
function area(label,key,placeholder=''){return `<label class="wide">${label}<textarea data-field="${key}" placeholder="${placeholder}">${esc(state[key])}</textarea></label>`}
function choice(label,sub,icon,selected,attrs,multi=false){return `<button class="choice ${selected?'selected':''} ${multi?'multi':''}" ${attrs} aria-pressed="${selected}"><span class="choice-icon">${icon}</span><span><strong>${esc(label)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span><span class="radio"></span></button>`}
